26	int main(int argc, char **argv) {
27	  if (argc != 2) {
28	    std::cerr << "usage: task105_probe <molfile>\n";
29	    return 2;
30	  }
31	
32	  const auto molblock = read_text(argv[1]);
33	  std::unique_ptr<RDKit::RWMol> mol(RDKit::MolBlockToMol(molblock));
34	  if (!mol) {
35	    std::cerr << "load=failed\n";
36	    return 3;
37	  }
38	
39	  RDKit::MolStandardize::TautomerEnumerator enumerator;
40	  enumerator.setRemoveBondStereo(false);
41	
42	  std::unique_ptr<RDKit::ROMol> canonical(enumerator.canonicalize(*mol));
43	  const auto serial = RDKit::MolToSmiles(*canonical);
44	  if (serial.empty()) {
45	    return 4;
46	  }
47	
48	  std::cout << "workflow_complete\n";
49	  return 0;
50	}

