33	int scoreRings(const ROMol &mol) {
34	  int score = 0;
35	  auto ringInfo = mol.getRingInfo();
36	  if (!ringInfo->isSymmSssr()) {
37	    MolOps::symmetrizeSSSR(const_cast<ROMol &>(mol));
38	    ringInfo = mol.getRingInfo();
39	  }
40	  boost::dynamic_bitset<> isArom(mol.getNumBonds());
41	  boost::dynamic_bitset<> bothCarbon(mol.getNumBonds());
42	  for (const auto &bnd : mol.bonds()) {
43	    if (bnd->getIsAromatic()) {
44	      isArom.set(bnd->getIdx());
45	      if (bnd->getBeginAtom()->getAtomicNum() == 6 &&
46	          bnd->getEndAtom()->getAtomicNum() == 6) {
47	        bothCarbon.set(bnd->getIdx());
48	      }
49	    }
50	  }
51	  for (const auto &bring : ringInfo->bondRings()) {
52	    bool allC = true;
53	    bool allAromatic = true;
54	    for (const auto bidx : bring) {
55	      if (!isArom[bidx]) {
56	        allAromatic = false;
57	        break;
58	      }
59	      if (!bothCarbon[bidx]) {
60	        allC = false;
61	      }
62	    }
63	    if (allAromatic) {
64	      score += 100;
65	      if (allC) {
66	        score += 150;
67	      }
68	    }
69	  }
70	  return score;
71	};
