94	const std::vector<SubstructTerm> &getDefaultTautomerScoreSubstructs() {
95	  // Each term specifies:
96	  //   - name, SMARTS, score
97	  //   - requiredElements: atomic numbers that must be present (empty = no filter)
98	  //   - connectivitySmarts: bond-order-agnostic pattern for pre-screening
99	  // Since tautomerization only moves H and changes bond orders (never creates/
100	  // destroys heavy-atom bonds), we can skip patterns whose connectivity
101	  // prerequisites aren't met by the input molecule.
102	  static std::vector<SubstructTerm> substructureTerms{
103	      {"benzoquinone", "[#6]1([#6]=[#6][#6]([#6]=[#6]1)=,:[N,S,O])=,:[N,S,O]", 25, {6}, "[#6]1(~[#6]~[#6]~[#6](~[#6]~[#6]~1)~[N,S,O])~[N,S,O]"},
104	      {"oxim", "[#6]=[N][OH]", 4, {6, 7, 8}, "[#6]~[#7]~[#8]"},
105	      {"C=O", "[#6]=,:[#8]", 2, {6, 8}, "[#6]~[#8]"},
106	      {"N=O", "[#7]=,:[#8]", 2, {7, 8}, "[#7]~[#8]"},
107	      {"P=O", "[#15]=,:[#8]", 2, {15, 8}, "[#15]~[#8]"},
108	      {"C=hetero", "[C]=[!#1;!#6]", 1, {6}, "[C]~[!#1;!#6]"},
109	      {"C(=hetero)-hetero", "[C](=[!#1;!#6])[!#1;!#6]", 2, {6}, "[C](~[!#1;!#6])~[!#1;!#6]"},
110	      {"aromatic C = exocyclic N", "[c]=!@[N]", -1, {6, 7}, "[c]~[N]"},
111	      {"methyl", "[CX4H3]", 1, {6}, ""},
112	      {"guanidine terminal=N", "[#7]C(=[NR0])[#7H0]", 1, {6, 7}, "[#7]~[#6]~[#7]"},
113	      {"guanidine endocyclic=N", "[#7;R][#6;R]([N])=[#7;R]", 2, {6, 7}, "[#7]~[#6](~[N])~[#7]"},
114	      {"aci-nitro", "[#6]=[N+]([O-])[OH]", -4, {6, 7, 8}, "[#6]~[#7](~[#8])~[#8]"}};
115	  return substructureTerms;
116	}
