162	// ---------------------------------------------------------------------------
163	// Specialized matchers for simple scoring patterns.
164	// These avoid VF2 graph matching overhead by directly iterating atoms/bonds.
165	// Each function is equivalent to the corresponding SMARTS pattern but runs
166	// in O(n) time without the graph isomorphism overhead.
167	// ---------------------------------------------------------------------------
168	
169	// Count bonds between two element types with double or aromatic bond order.
170	// Matches: [#elem1]=,:[#elem2]
171	inline unsigned int countDoubleOrAromaticBonds(const ROMol &mol, int elem1,
172	                                               int elem2) {
173	  unsigned int count = 0;
174	  for (const auto bond : mol.bonds()) {
175	    const auto bt = bond->getBondType();
176	    if (bt != Bond::DOUBLE && bt != Bond::AROMATIC) {
177	      continue;
178	    }
179	    const int a1 = bond->getBeginAtom()->getAtomicNum();
180	    const int a2 = bond->getEndAtom()->getAtomicNum();
181	    if ((a1 == elem1 && a2 == elem2) || (a1 == elem2 && a2 == elem1)) {
182	      ++count;
183	    }
184	  }
185	  return count;
186	}
187	
188	// Count methyl groups: [CX4H3] - sp3 carbon with exactly 3 total H
189	inline unsigned int countMethyls(const ROMol &mol) {
190	  unsigned int count = 0;
191	  for (const auto atom : mol.atoms()) {
192	    if (atom->getAtomicNum() != 6) {
193	      continue;
194	    }
195	    // X4 means total degree 4 (including implicit H)
196	    if (atom->getTotalDegree() != 4) {
197	      continue;
198	    }
199	    // H3 means exactly 3 total hydrogens
200	    if (atom->getTotalNumHs() != 3) {
201	      continue;
202	    }
203	    ++count;
204	  }
205	  return count;
206	}
207	
208	// Count [C]=[!#1;!#6] - aliphatic carbon double-bonded to heteroatom
209	inline unsigned int countCarbonDoubleHetero(const ROMol &mol) {
210	  unsigned int count = 0;
211	  for (const auto bond : mol.bonds()) {
212	    if (bond->getBondType() != Bond::DOUBLE) {
213	      continue;
214	    }
215	    const auto *a1 = bond->getBeginAtom();
216	    const auto *a2 = bond->getEndAtom();
217	    // [C] is aliphatic carbon (not aromatic)
218	    // Check C double-bonded to heteroatom (not H, not C)
219	    auto isAliphaticCarbonToHetero = [](const Atom *c, const Atom *het) {
220	      return c->getAtomicNum() == 6 && !c->getIsAromatic() &&
221	             het->getAtomicNum() != 1 && het->getAtomicNum() != 6;
222	    };
223	    if (isAliphaticCarbonToHetero(a1, a2) ||
224	        isAliphaticCarbonToHetero(a2, a1)) {
225	      ++count;
226	    }
227	  }
228	  return count;
229	}
230	
231	// Count [c]=!@[N] - aromatic carbon double-bonded to nitrogen (exocyclic)
232	inline unsigned int countAromaticCarbonExocyclicN(const ROMol &mol) {
233	  unsigned int count = 0;
234	  const auto *ringInfo = mol.getRingInfo();
235	  for (const auto bond : mol.bonds()) {
236	    if (bond->getBondType() != Bond::DOUBLE) {
237	      continue;
238	    }
239	    // !@ means bond not in ring
240	    if (ringInfo->numBondRings(bond->getIdx()) > 0) {
241	      continue;
242	    }
243	    const auto *a1 = bond->getBeginAtom();
244	    const auto *a2 = bond->getEndAtom();
245	    // [c] is aromatic carbon, [N] is any nitrogen
246	    auto isAromaticCarbonToN = [](const Atom *c, const Atom *n) {
247	      return c->getAtomicNum() == 6 && c->getIsAromatic() &&
248	             n->getAtomicNum() == 7;
249	    };
250	    if (isAromaticCarbonToN(a1, a2) || isAromaticCarbonToN(a2, a1)) {
251	      ++count;
252	    }
253	  }
254	  return count;
255	}
