257	// Indices of the scoring patterns with dedicated matchers.
258	// These must match the order of patterns in getDefaultTautomerScoreSubstructs().
259	namespace {
260	enum class PatternIdx {
261	  CarbonylO = 2,
262	  NO = 3,
263	  PO = 4,
264	  CHetero = 5,
265	  AromaticCN = 7,
266	  Methyl = 8,
267	};
268	}  // namespace
269	
270	int scoreSubstructsFiltered(const ROMol &mol,
271	                            const std::vector<SubstructTerm> &terms,
272	                            const std::vector<size_t> &relevantIndices) {
273	  int score = 0;
274	  SubstructMatchParameters params;
275	
276	  for (const size_t idx : relevantIndices) {
277	    const auto &term = terms[idx];
278	    if (!term.matcher.getNumAtoms()) {
279	      continue;
280	    }
281	
282	    unsigned int nMatches = 0;
283	
284	    // Use specialized matchers for simple patterns, VF2 for complex ones
285	    switch (static_cast<PatternIdx>(idx)) {
286	      case PatternIdx::CarbonylO:
287	        nMatches = countDoubleOrAromaticBonds(mol, 6, 8);  // C=O
288	        break;
289	      case PatternIdx::NO:
290	        nMatches = countDoubleOrAromaticBonds(mol, 7, 8);  // N=O
291	        break;
292	      case PatternIdx::PO:
293	        nMatches = countDoubleOrAromaticBonds(mol, 15, 8);  // P=O
294	        break;
295	      case PatternIdx::CHetero:
296	        nMatches = countCarbonDoubleHetero(mol);
297	        break;
298	      case PatternIdx::AromaticCN:
299	        nMatches = countAromaticCarbonExocyclicN(mol);
300	        break;
301	      case PatternIdx::Methyl:
302	        nMatches = countMethyls(mol);
303	        break;
304	      default:
305	        // Fall back to VF2 for complex patterns (benzoquinone, oxim,
306	        // C(=hetero)-hetero, guanidine, aci-nitro)
307	        nMatches = SubstructMatchCount(mol, term.matcher, params);
308	        break;
309	    }
310	
311	    score += static_cast<int>(nMatches) * term.score;
312	  }
313	  return score;
314	}
315	
316	int scoreSubstructs(const ROMol &mol,
317	                    const std::vector<SubstructTerm> &substructureTerms) {
318	  int score = 0;
319	  SubstructMatchParameters params;
320	  for (const auto &term : substructureTerms) {
321	    if (!term.matcher.getNumAtoms()) {
322	      BOOST_LOG(rdErrorLog) << " matcher for term " << term.name
323	                            << " is invalid, ignoring it." << std::endl;
324	      continue;
325	    }
326	    const auto nMatches = SubstructMatchCount(mol, term.matcher, params);
327	    score += static_cast<int>(nMatches) * term.score;
328	  }
329	  return score;
330	}
