332	int scoreHeteroHs(const ROMol &mol) {
333	  int score = 0;
334	  for (const auto &at : mol.atoms()) {
335	    int anum = at->getAtomicNum();
336	    if (anum == 15 || anum == 16 || anum == 34 || anum == 52) {
337	      score -= at->getTotalNumHs();
338	    }
339	  }
340	  return score;
341	}
