510	std::vector<ROMOL_SPTR> TautomerEnumerator::enumerate(
511	    const ROMol &mol, boost::dynamic_bitset<> *modifiedAtoms,
512	    boost::dynamic_bitset<> *modifiedBonds) const {
513	  TautomerEnumeratorResult tresult = enumerate(mol);
514	  if (modifiedAtoms) {
515	    *modifiedAtoms = tresult.modifiedAtoms();
516	  }
517	  if (modifiedBonds) {
518	    *modifiedBonds = tresult.modifiedBonds();
519	  }
520	  return tresult.tautomers();
521	}
522	
523	TautomerEnumeratorResult TautomerEnumerator::enumerate(const ROMol &mol) const {
524	#ifdef VERBOSE_ENUMERATION
525	  std::cout << "**********************************" << std::endl;
526	#endif
527	  PRECONDITION(dp_catalog, "no catalog!");
528	  const TautomerCatalogParams *tautparams = dp_catalog->getCatalogParams();
529	  PRECONDITION(tautparams, "");
530	
531	  TautomerEnumeratorResult res;
532	
533	  const std::vector<TautomerTransform> &transforms =
534	      tautparams->getTransforms();
535	
536	  // Enumerate all possible tautomers and return them as a vector.
537	  // smi is the input molecule SMILES
538	  std::string smi = MolToSmiles(mol, true);
539	  // taut is a copy of the input molecule
540	  ROMOL_SPTR taut(new ROMol(mol));
541	  // do whatever sanitization bits are required
542	  if (taut->needsUpdatePropertyCache()) {
543	    taut->updatePropertyCache(false);
544	  }
545	  if (!taut->getRingInfo()->isSymmSssr()) {
546	    MolOps::symmetrizeSSSR(*taut);
547	  }
548	
549	  // Kekulized form will be created lazily when needed for transform matching.
550	  // canonical=true is used on demand so that tautomer deduplication is
551	  // independent of atom ordering in the molecule.
552	  res.d_tautomers = {{smi, Tautomer(taut, 0, 0)}};
553	  res.d_modifiedAtoms.resize(mol.getNumAtoms());
554	  res.d_modifiedBonds.resize(mol.getNumBonds());
555	
556	  // Keep running counts of modified atoms/bonds.
557	  // `boost::dynamic_bitset<>::count()` is O(n) in the number of blocks, and we
558	  // were previously calling it once per new tautomer, which is avoidable.
559	  size_t numModifiedAtoms = 0;
560	  size_t numModifiedBonds = 0;
561	  const auto markAtomModified = [&res, &numModifiedAtoms](unsigned int idx) {
562	    if (!res.d_modifiedAtoms.test(idx)) {
563	      res.d_modifiedAtoms.set(idx);
564	      ++numModifiedAtoms;
565	    }
566	  };
567	  const auto markBondModified = [&res, &numModifiedBonds](unsigned int idx) {
568	    if (!res.d_modifiedBonds.test(idx)) {
569	      res.d_modifiedBonds.set(idx);
570	      ++numModifiedBonds;
571	    }
572	  };
573	  bool completed = false;
574	  bool bailOut = false;
575	  unsigned int nTransforms = 0;
576	  static const std::array<const char *, 4> statusMsg{
577	      "completed", "max tautomers reached", "max transforms reached",
578	      "canceled"};
579	
580	  while (!completed && !bailOut) {
581	    // std::map automatically sorts res.d_tautomers into alphabetical order
582	    // (SMILES)
583	    for (auto &smilesTautomerPair : res.d_tautomers) {
584	#ifdef VERBOSE_ENUMERATION
585	      std::cout << "Current tautomers: " << std::endl;
586	      for (const auto &smilesTautomerPair : res.d_tautomers) {
587	        std::cout << smilesTautomerPair.first << " done "
588	                  << smilesTautomerPair.second.d_done << std::endl;
589	      }
590	#endif
591	      std::string tsmiles;
592	      if (smilesTautomerPair.second.d_done) {
593	#ifdef VERBOSE_ENUMERATION
594	        std::cout << "Skipping " << smilesTautomerPair.first
595	                  << " as already done" << std::endl;
596	#endif
597	        continue;
598	      }
599	#ifdef VERBOSE_ENUMERATION
600	      std::cout << "Looking at tautomer: " << smilesTautomerPair.first
601	                << std::endl;
602	#endif
603	      // tautomer not yet done
604	      for (const auto &transform : transforms) {
605	        if (bailOut) {
606	          break;
607	        }
608	        // kmol is the kekulized version of the tautomer (created lazily)
609	        const auto &kmol = smilesTautomerPair.second.getKekulized();
610	        std::vector<MatchVectType> matches;
611	        unsigned int matched = SubstructMatch(*kmol, *(transform.Mol), matches);
612	
613	        if (!matched) {
614	          continue;
615	        }
616	        ++nTransforms;
617	#ifdef VERBOSE_ENUMERATION
618	        std::string name;
619	        (transform.Mol)->getProp(common_properties::_Name, name);
620	        SmilesWriteParams smilesWriteParams;
621	        smilesWriteParams.allBondsExplicit = true;
622	        std::cout << "kmol for " << smilesTautomerPair.first << " : "
623	                  << MolToSmiles(*kmol, smilesWriteParams) << std::endl;
624	        std::cout << "transform mol: " << MolToSmarts(*(transform.Mol))
625	                  << std::endl;
626	
627	        std::cout << "Matched: " << name << std::endl;
628	#endif
629	        // loop over transform matches
630	        for (const auto &match : matches) {
631	          if (nTransforms >= d_maxTransforms) {
632	            res.d_status = TautomerEnumeratorStatus::MaxTransformsReached;
633	            bailOut = true;
634	          } else if (res.d_tautomers.size() >= d_maxTautomers) {
635	            res.d_status = TautomerEnumeratorStatus::MaxTautomersReached;
636	            bailOut = true;
637	          } else if (d_callback.get() && !(*d_callback)(mol, res)) {
638	            res.d_status = TautomerEnumeratorStatus::Canceled;
639	            bailOut = true;
640	          }
641	          if (bailOut) {
642	            break;
643	          }
644	          // Create a copy of in the input molecule so we can modify it
645	          // Use kekule form so bonds are explicitly single/double instead of
646	          // aromatic
647	          RWMOL_SPTR product(new RWMol(*kmol, true));
648	          // Remove a hydrogen from the first matched atom and add one to the
649	          // last
650	          int firstIdx = match.front().second;
651	          int lastIdx = match.back().second;
652	          Atom *first = product->getAtomWithIdx(firstIdx);
653	          Atom *last = product->getAtomWithIdx(lastIdx);
654	          markAtomModified(static_cast<unsigned int>(firstIdx));
655	          markAtomModified(static_cast<unsigned int>(lastIdx));
656	          first->setNumExplicitHs(
657	              std::max(0, static_cast<int>(first->getTotalNumHs()) - 1));
658	          last->setNumExplicitHs(last->getTotalNumHs() + 1);
659	          // Remove any implicit hydrogens from the first and last atoms
660	          // now we have set the count explicitly
661	          first->setNoImplicit(true);
662	          last->setNoImplicit(true);
663	          // Adjust bond orders
664	          unsigned int bi = 0;
665	          for (size_t i = 0; i < transform.Mol->getNumBonds(); ++i) {
666	            const auto tbond = transform.Mol->getBondWithIdx(i);
667	            Bond *bond = product->getBondBetweenAtoms(
668	                match[tbond->getBeginAtomIdx()].second,
669	                match[tbond->getEndAtomIdx()].second);
670	            ASSERT_INVARIANT(bond, "required bond not found");
671	            // check if bonds is specified in tautomer.in file
672	            if (!transform.BondTypes.empty()) {
673	              bond->setBondType(transform.BondTypes[bi]);
674	              ++bi;
675	            } else {
676	              Bond::BondType bondtype = bond->getBondType();
677	#ifdef VERBOSE_ENUMERATION
678	              std::cout << "Bond as double: " << bond->getBondTypeAsDouble()
679	                        << std::endl;
680	              std::cout << bondtype << std::endl;
681	#endif
682	              if (bondtype == Bond::SINGLE) {
683	                bond->setBondType(Bond::DOUBLE);
684	#ifdef VERBOSE_ENUMERATION
685	                std::cout << "Set bond to double" << std::endl;
686	#endif
687	              }
688	              if (bondtype == Bond::DOUBLE) {
689	                bond->setBondType(Bond::SINGLE);
690	#ifdef VERBOSE_ENUMERATION
691	                std::cout << "Set bond to single" << std::endl;
692	#endif
693	              }
694	            }
695	            markBondModified(bond->getIdx());
696	          }
697	          // TODO adjust charges
698	          if (!transform.Charges.empty()) {
699	            unsigned int ci = 0;
700	            for (const auto &pair : match) {
701	              Atom *atom = product->getAtomWithIdx(pair.second);
702	              atom->setFormalCharge(atom->getFormalCharge() +
703	                                    transform.Charges[ci++]);
704	            }
705	          }
706	#ifdef VERBOSE_ENUMERATION
707	          {
708	            SmilesWriteParams smilesWriteParams;
709	            smilesWriteParams.allBondsExplicit = true;
710	            std::cout << "pre-sanitize: "
711	                      << MolToSmiles(*product, smilesWriteParams) << std::endl;
712	          }
713	#endif
714	
715	          try {
716	            // We only change bond orders/H counts/charges; the molecular graph
717	            // (and therefore ring topology) is unchanged.
718	            // `sanitizeMol()` always calls `clearComputedProps()` which resets
719	            // ring info and forces ring-finding for each generated tautomer.
720	            // Avoid that by clearing computed props without touching rings,
721	            // then running the specific sanitize steps we need.
722	            product->clearComputedProps(false);
723	            product->updatePropertyCache(false);
724	            MolOps::Kekulize(*product);
725	            MolOps::setAromaticity(*product);
726	            MolOps::setConjugation(*product);
727	            MolOps::setHybridization(*product);
728	            MolOps::adjustHs(*product);
729	          } catch (const KekulizeException &) {
730	            continue;
731	          }
732	#ifdef VERBOSE_ENUMERATION
733	          SmilesWriteParams smilesWriteParams;
734	          smilesWriteParams.allBondsExplicit = true;
735	          std::cout << "pre-setTautomerStereo: "
736	                    << MolToSmiles(*product, smilesWriteParams) << std::endl;
737	#endif
738	          setTautomerStereoAndIsoHs(mol, *product, res);
739	          tsmiles = MolToSmiles(*product, true);
740	#ifdef VERBOSE_ENUMERATION
741	          (transform.Mol)->getProp(common_properties::_Name, name);
742	          std::cout << "Applied rule: " << name << " to "
743	                    << smilesTautomerPair.first << std::endl;
744	#endif
745	          if (res.d_tautomers.find(tsmiles) != res.d_tautomers.end()) {
746	#ifdef VERBOSE_ENUMERATION
747	            std::cout << "Previous tautomer produced again: " << tsmiles
748	                      << std::endl;
749	#endif
750	            continue;
751	          }
752	          // in addition to the above transformations, sanitization may modify
753	          // bonds, e.g. Cc1nc2ccccc2[nH]1
754	          // Use parallel iteration to avoid O(n) getBondWithIdx lookups
755	          {
756	            auto productBondIt = product->bonds().begin();
757	            for (const auto molBond : mol.bonds()) {
758	              const auto productBond = *productBondIt;
759	              ++productBondIt;
760	              auto i = molBond->getIdx();
761	              if (molBond->getBondType() != productBond->getBondType() &&
762	                  !res.d_modifiedBonds.test(i)) {
763	#ifdef VERBOSE_ENUMERATION
764	                std::cout << "Sanitization has modified bond " << i
765	                          << std::endl;
766	#endif
767	                markBondModified(static_cast<unsigned int>(i));
768	              }
769	            }
770	          }
771	          // Kekulized form will be created lazily when needed;
772	          // canonical=true is used on demand for order-independent deduplication.
773	#ifdef VERBOSE_ENUMERATION
774	          auto it = res.d_tautomers.find(tsmiles);
775	          if (it == res.d_tautomers.end()) {
776	            std::cout << "New tautomer added as ";
777	          } else {
778	            std::cout << "New tautomer replaced for ";
779	          }
780	          std::cout << tsmiles << ", taut: " << MolToSmiles(*product)
781	                    << std::endl;
782	#endif
783	          // BOOST_LOG(rdInfoLog)
784	          //     << "Tautomer transform "
785	          //     <<
786	          //     transform.Mol->getProp<std::string>(common_properties::_Name)
787	          //     << " produced tautomer " << tsmiles << std::endl;
788	          res.d_tautomers[tsmiles] = Tautomer(
789	              std::move(product),
790	              numModifiedAtoms, numModifiedBonds);
791	        }
792	      }
793	      smilesTautomerPair.second.d_done = true;
794	    }
795	    completed = true;
796	    size_t maxNumModifiedAtoms = numModifiedAtoms;
797	    size_t maxNumModifiedBonds = numModifiedBonds;
798	    for (auto it = res.d_tautomers.begin(); it != res.d_tautomers.end();) {
799	      auto &taut = it->second;
800	      if (!taut.d_done) {
801	        completed = false;
802	      }
803	      if ((taut.d_numModifiedAtoms < maxNumModifiedAtoms ||
804	           taut.d_numModifiedBonds < maxNumModifiedBonds) &&
805	          setTautomerStereoAndIsoHs(mol, *taut.tautomer, res)) {
806	        Tautomer tautStored = std::move(taut);
807	        it = res.d_tautomers.erase(it);
808	        tautStored.d_numModifiedAtoms = maxNumModifiedAtoms;
809	        tautStored.d_numModifiedBonds = maxNumModifiedBonds;
810	        auto insertRes = res.d_tautomers.insert(std::make_pair(
811	            MolToSmiles(*tautStored.tautomer), std::move(tautStored)));
812	        if (insertRes.second) {
813	          it = insertRes.first;
814	        }
815	      } else {
816	        ++it;
817	      }
818	    }
819	    if (bailOut && res.d_tautomers.size() < d_maxTautomers &&
820	        res.d_status == TautomerEnumeratorStatus::MaxTautomersReached) {
821	      res.d_status = TautomerEnumeratorStatus::Completed;
822	      bailOut = false;
823	    }
824	  }  // while
825	  res.fillTautomersItVec();
826	  if (!completed) {
827	    BOOST_LOG(rdWarningLog)
828	        << "Tautomer enumeration stopped at " << res.d_tautomers.size()
829	        << " tautomers: " << statusMsg.at(static_cast<size_t>(res.d_status))
830	        << std::endl;
831	  }
832	
833	  return res;
834	}
