872	ROMol *TautomerEnumerator::canonicalize(
873	    const ROMol &mol, boost::function<int(const ROMol &mol)> scoreFunc) const {
874	  auto thisCopy = TautomerEnumerator(*this);
875	  thisCopy.setReassignStereo(false);
876	  auto res = thisCopy.enumerate(mol);
877	  if (res.empty()) {
878	    BOOST_LOG(rdWarningLog)
879	        << "no tautomers found, returning input molecule" << std::endl;
880	    return new ROMol(mol);
881	  }
882	  // When no custom scorer provided, use optimized scoring that pre-filters
883	  // SubstructTerm patterns once for the input molecule rather than evaluating
884	  // all 12 substructure matches per tautomer. This is safe because
885	  // tautomerization only moves H and changes bond orders, never creates or
886	  // destroys heavy-atom bonds.
887	  if (!scoreFunc) {
888	    scoreFunc = TautomerScoringFunctions::makeOptimizedScorer(mol);
889	  }
890	  ROMol *canonical = pickCanonical(res, scoreFunc);
891	  // quickCopy during enumeration doesn't copy molecule properties or
892	  // conformers.  Restore both from the original molecule so that
893	  // downstream code (e.g. InChI generation) that relies on 2D/3D
894	  // coordinates or mol-level properties works correctly.
895	  canonical->updateProps(mol);
896	  for (auto confIt = mol.beginConformers(); confIt != mol.endConformers();
897	       ++confIt) {
898	    canonical->addConformer(new Conformer(**confIt), true);
899	  }
900	  return canonical;
901	}
902	
903	void TautomerEnumerator::canonicalizeInPlace(
904	    RWMol &mol, boost::function<int(const ROMol &mol)> scoreFunc) const {
905	  auto thisCopy = TautomerEnumerator(*this);
906	  thisCopy.setReassignStereo(false);
907	  auto res = thisCopy.enumerate(mol);
908	  if (res.empty()) {
909	    BOOST_LOG(rdWarningLog)
910	        << "no tautomers found, molecule unchanged" << std::endl;
911	    return;
912	  }
913	  // When no custom scorer provided, use optimized scoring that pre-filters
914	  // SubstructTerm patterns once for the input molecule.
915	  if (!scoreFunc) {
916	    scoreFunc = TautomerScoringFunctions::makeOptimizedScorer(mol);
917	  }
918	  std::unique_ptr<ROMol> tmp{pickCanonical(res, scoreFunc)};
919	
920	  TEST_ASSERT(tmp->getNumAtoms() == mol.getNumAtoms());
921	  TEST_ASSERT(tmp->getNumBonds() == mol.getNumBonds());
922	  // now copy the info from the canonical tautomer over to the input molecule
923	  // iterate both molecules' atoms and bonds in parallel - they have matching indices
924	  {
925	    auto molAtomIt = mol.atoms().begin();
926	    for (const auto tmpAtom : tmp->atoms()) {
927	      auto atom = *molAtomIt;
928	      ++molAtomIt;
929	      TEST_ASSERT(tmpAtom->getAtomicNum() == atom->getAtomicNum());
930	      atom->setFormalCharge(tmpAtom->getFormalCharge());
931	      atom->setNoImplicit(tmpAtom->getNoImplicit());
932	      atom->setIsAromatic(tmpAtom->getIsAromatic());
933	      atom->setNumExplicitHs(tmpAtom->getNumExplicitHs());
934	      atom->setNumRadicalElectrons(tmpAtom->getNumRadicalElectrons());
935	      atom->setChiralTag(tmpAtom->getChiralTag());
936	    }
937	  }
938	  {
939	    auto molBondIt = mol.bonds().begin();
940	    for (const auto tmpBond : tmp->bonds()) {
941	      auto bond = *molBondIt;
942	      ++molBondIt;
943	      TEST_ASSERT(tmpBond->getBeginAtomIdx() == bond->getBeginAtomIdx());
944	      TEST_ASSERT(tmpBond->getEndAtomIdx() == bond->getEndAtomIdx());
945	      bond->setBondType(tmpBond->getBondType());
946	      bond->setBondDir(tmpBond->getBondDir());
947	      bond->setIsAromatic(tmpBond->getIsAromatic());
948	      bond->setIsConjugated(tmpBond->getIsConjugated());
949	      if (tmpBond->getStereoAtoms().size() == 2) {
950	        bond->setStereoAtoms(tmpBond->getStereoAtoms()[0],
951	                             tmpBond->getStereoAtoms()[1]);
952	      }
953	      bond->setStereo(tmpBond->getStereo());
954	    }
955	  }
956	  mol.updatePropertyCache(false);
957	}
