216	      ++d_it;
217	      return *this;
218	    }
219	    const_iterator operator--(int) {
220	      const_iterator copy(d_it);
221	      operator--();
222	      return copy;
223	    }
224	    const_iterator &operator--() {
225	      --d_it;
226	      return *this;
227	    }
