54	const Atom *getNonsharedAtom(const Bond &bond1, const Bond &bond2) {
55	  if (bond1.getBeginAtomIdx() == bond2.getBeginAtomIdx() ||
56	      bond1.getBeginAtomIdx() == bond2.getEndAtomIdx()) {
57	    return bond1.getEndAtom();
58	  } else if (bond1.getEndAtomIdx() == bond2.getBeginAtomIdx() ||
59	             bond1.getEndAtomIdx() == bond2.getEndAtomIdx()) {
60	    return bond1.getBeginAtom();
61	  }
62	  POSTCONDITION(0, "bonds don't share an atom");
63	}
