65	const unsigned StereoBondThresholds::DBL_BOND_NO_STEREO;
66	const unsigned StereoBondThresholds::DBL_BOND_SPECIFIED_STEREO;
67	const unsigned StereoBondThresholds::CHIRAL_ATOM;
68	const unsigned StereoBondThresholds::DIRECTION_SET;
69	
70	// a note on the way the StereoBondThresholds are used:
71	//  the penalties are all 1/10th of the corresponding threshold, so
72	//  the penalty for being connected to a chiral atom is
73	//  StereoBondThresholds::CHIRAL_ATOM/10
74	//  This allows us to just add up the penalties for a particular
75	//  single bond and still use one set of thresholds - an individual
76	//  single bond will never have any particular penalty term applied
77	//  more than a couple of times
78	//
79	void addWavyBondsForStereoAny(ROMol &mol, bool clearDoubleBondFlags,
80	                              unsigned addWhenImpossible) {
81	  std::vector<int> singleBondScores(mol.getNumBonds(), 0);
82	  // used to store the double bond neighbors, if any, of each single bond
83	  std::map<unsigned, std::vector<unsigned>> singleBondNeighbors;
84	  boost::dynamic_bitset<> doubleBondsToSet(mol.getNumBonds());
85	  // mark single bonds adjacent to double bonds
86	  for (const auto dblBond : mol.bonds()) {
87	    if (dblBond->getBondType() != Bond::BondType::DOUBLE) {
88	      continue;
89	    }
90	    if (dblBond->getStereo() == Bond::BondStereo::STEREOANY) {
91	      doubleBondsToSet.set(dblBond->getIdx());
92	    }
93	    for (auto singleBond : getBondNeighbors(mol, *dblBond)) {
94	      if (singleBond->getBondType() != Bond::BondType::SINGLE) {
95	        continue;
96	      }
97	      // NOTE: we could make this canonical by initializing scores to the
98	      // canonical atom ranks
99	      int score = singleBondScores[singleBond->getIdx()];
100	      ++score;
101	
102	      // penalty for having a direction already set
103	      if (singleBond->getBondDir() != Bond::BondDir::NONE) {
104	        score += StereoBondThresholds::DIRECTION_SET / 10;
105	      }
106	
107	      // penalties from the double bond itself:
108	
109	      // penalize being adjacent to a double bond with empty stereo:
110	      if (dblBond->getStereo() == Bond::BondStereo::STEREONONE) {
111	        score += StereoBondThresholds::DBL_BOND_NO_STEREO / 10;
112	      } else if (dblBond->getStereo() > Bond::BondStereo::STEREOANY) {
113	        // penalize being adjacent to a double bond with specified stereo:
114	        score += StereoBondThresholds::DBL_BOND_SPECIFIED_STEREO / 10;
115	      }
116	
117	      // atom-related penalties
118	      auto otherAtom = getNonsharedAtom(*singleBond, *dblBond);
119	      // favor atoms with smaller numbers of neighbors:
120	      score += 10 * otherAtom->getDegree();
121	      // penalty for being adjacent to an atom with specified stereo
122	      if (otherAtom->getChiralTag() != Atom::ChiralType::CHI_UNSPECIFIED &&
123	          otherAtom->getChiralTag() != Atom::ChiralType::CHI_OTHER) {
124	        score += StereoBondThresholds::CHIRAL_ATOM / 10;
125	      }
126	      singleBondScores[singleBond->getIdx()] = score;
127	      if (dblBond->getStereo() == Bond::BondStereo::STEREOANY) {
128	        singleBondNeighbors[singleBond->getIdx()].push_back(dblBond->getIdx());
129	      }
130	    }
131	  }
132	  std::vector<std::tuple<int, unsigned int, size_t>> sortedScores;
133	  for (size_t i = 0; i < mol.getNumBonds(); ++i) {
134	    auto score = singleBondScores[i];
135	    if (!score) {
136	      continue;
137	    }
138	    sortedScores.push_back(
139	        std::make_tuple(-1 * singleBondNeighbors[i].size(), score, i));
140	  }
141	  std::sort(sortedScores.begin(), sortedScores.end());
142	  for (const auto &tpl : sortedScores) {
143	    // FIX: check if dir is already set
144	    for (auto dblBondIdx : singleBondNeighbors[std::get<2>(tpl)]) {
145	      if (doubleBondsToSet[dblBondIdx]) {
146	        if (addWhenImpossible) {
147	          if (std::get<1>(tpl) > addWhenImpossible) {
148	            continue;
149	          }
150	        } else if (std::get<1>(tpl) >
151	                   StereoBondThresholds::DBL_BOND_NO_STEREO) {
152	          BOOST_LOG(rdWarningLog)
153	              << "Setting wavy bond flag on bond " << std::get<2>(tpl)
154	              << " which may make other stereo info ambiguous" << std::endl;
155	        }
156	        mol.getBondWithIdx(std::get<2>(tpl))
157	            ->setBondDir(Bond::BondDir::UNKNOWN);
158	        if (clearDoubleBondFlags) {
159	          auto dblBond = mol.getBondWithIdx(dblBondIdx);
160	          if (dblBond->getBondDir() == Bond::BondDir::EITHERDOUBLE) {
161	            dblBond->setBondDir(Bond::BondDir::NONE);
162	          }
163	          dblBond->setStereo(Bond::BondStereo::STEREONONE);
164	        }
165	        doubleBondsToSet.reset(dblBondIdx);
166	      }
167	    }
168	  }
169	  if (addWhenImpossible) {
170	    if (doubleBondsToSet.count()) {
171	      std::stringstream sstr;
172	      sstr << " unable to set wavy bonds for double bonds:";
173	      for (size_t i = 0; i < mol.getNumBonds(); ++i) {
174	        if (doubleBondsToSet[i]) {
175	          sstr << " " << i;
176	        }
177	      }
178	      BOOST_LOG(rdWarningLog) << sstr.str() << std::endl;
179	    }
180	  }
