230	void markUnspecifiedStereoAsUnknown(ROMol &mol, int confId) {
231	  PRECONDITION(mol.getNumConformers(), "no conformer");
232	  const auto conf = mol.getConformer(confId);
233	  auto wedgeBonds = RDKit::Chirality::pickBondsToWedge(mol, nullptr, &conf);
234	  for (auto b : mol.bonds()) {
235	    if (b->getBondType() == Bond::DOUBLE) {
236	      int dirCode;
237	      bool reverse;
238	      RDKit::Chirality::GetMolFileBondStereoInfo(b, wedgeBonds, &conf, dirCode,
239	                                                 reverse);
240	      if (dirCode == 3) {
241	        b->setStereo(Bond::STEREOANY);
242	      }
243	    }
244	  }
245	  static int noNbrs = 100;
246	  auto si = Chirality::findPotentialStereo(mol);
247	  if (si.size()) {
248	    std::pair<bool, INT_VECT> retVal =
249	        Chirality::detail::countChiralNbrs(mol, noNbrs);
250	    INT_VECT nChiralNbrs = retVal.second;
251	    for (auto i : si) {
252	      if (i.type == Chirality::StereoType::Atom_Tetrahedral &&
253	          i.specified == Chirality::StereoSpecified::Unspecified) {
254	        i.specified = Chirality::StereoSpecified::Unknown;
255	        auto atom = mol.getAtomWithIdx(i.centeredOn);
256	        std::map<int, std::unique_ptr<RDKit::Chirality::WedgeInfoBase>>
257	            resSoFar;
258	        int bndIdx = Chirality::detail::pickBondToWedge(atom, mol, nChiralNbrs,
259	                                                        resSoFar, noNbrs);
260	        auto bond = mol.getBondWithIdx(bndIdx);
261	        bond->setBondDir(Bond::UNKNOWN);
262	      }
263	    }
264	  }
