267	void translateChiralFlagToStereoGroups(ROMol &mol,
268	                                       StereoGroupType zeroFlagGroupType) {
269	  if (!mol.hasProp(common_properties::_MolFileChiralFlag)) {
270	    return;
271	  }
272	  int flagVal = 0;
273	  mol.getProp(common_properties::_MolFileChiralFlag, flagVal);
274	  mol.clearProp(common_properties::_MolFileChiralFlag);
275	
276	  StereoGroupType sgType =
277	      flagVal ? StereoGroupType::STEREO_ABSOLUTE : zeroFlagGroupType;
278	
279	  auto sgs = mol.getStereoGroups();
280	
281	  boost::dynamic_bitset<> sgAtoms(mol.getNumAtoms());
282	  boost::dynamic_bitset<> sgBonds(mol.getNumBonds());
283	  const StereoGroup *absGroup = nullptr;
284	  for (const auto &sg : sgs) {
285	    for (const auto aptr : sg.getAtoms()) {
286	      sgAtoms.set(aptr->getIdx());
287	    }
288	    for (const auto bptr : sg.getBonds()) {
289	      sgBonds.set(bptr->getIdx());
290	    }
291	    // if we already have an ABS group, we'll add to it
292	    if (sgType == StereoGroupType::STEREO_ABSOLUTE && !absGroup &&
293	        sg.getGroupType() == StereoGroupType::STEREO_ABSOLUTE) {
294	      absGroup = &sg;
295	    }
296	  }
297	  ROMol::ATOM_PTR_VECT stereoAts;
298	  ROMol::BOND_PTR_VECT stereoBds;
299	  for (const auto atom : mol.atoms()) {
300	    if (!sgAtoms[atom->getIdx()] &&
301	        (atom->getChiralTag() == Atom::ChiralType::CHI_TETRAHEDRAL_CCW ||
302	         atom->getChiralTag() == Atom::ChiralType::CHI_TETRAHEDRAL_CW)) {
303	      stereoAts.push_back(atom);
304	    }
305	  }
306	  for (const auto bond : mol.bonds()) {
307	    if (!sgBonds[bond->getIdx()] &&
308	        (bond->getStereo() == Bond::BondStereo::STEREOATROPCCW ||
309	         bond->getStereo() == Bond::BondStereo::STEREOATROPCW)) {
310	      stereoBds.push_back(bond);
311	    }
312	  }
313	  if (!stereoAts.empty() || !stereoBds.empty()) {
314	    if (!absGroup) {
315	      sgs.emplace_back(sgType, stereoAts, stereoBds, 0);
316	      mol.setStereoGroups(sgs);
317	    } else {
318	      std::vector<StereoGroup> newSgs;
319	      for (const auto &sg : sgs) {
320	        if (&sg != absGroup) {
321	          newSgs.push_back(sg);
322	        } else {
323	          ROMol::ATOM_PTR_VECT newStereoAtoms = sg.getAtoms();
324	          newStereoAtoms.insert(newStereoAtoms.end(), stereoAts.begin(),
325	                                stereoAts.end());
326	          ROMol::BOND_PTR_VECT newStereoBonds = sg.getBonds();
327	          newStereoBonds.insert(newStereoBonds.end(), stereoBds.begin(),
328	                                stereoBds.end());
329	
330	          newSgs.emplace_back(StereoGroupType::STEREO_ABSOLUTE, newStereoAtoms,
331	                              newStereoBonds, 0);
332	        }
333	      }
334	      mol.setStereoGroups(newSgs);
335	    }
336	  }
