807	    const auto bond = q.top();
808	    q.pop();
809	    if (seen_bonds[bond->getIdx()]) {
810	      continue;
811	    }
812	
813	    std::queue<Bond *> connectedBondsQ;
814	    connectedBondsQ.push(bond);
