#include <GraphMol/FileParsers/FileParsers.h>
#include <GraphMol/MolStandardize/Tautomer.h>
#include <GraphMol/RDKitBase.h>
#include <GraphMol/SmilesParse/SmilesWrite.h>
#include <RDGeneral/Invariant.h>

#include <fstream>
#include <iostream>
#include <memory>
#include <sstream>
#include <string>

namespace {

std::string read_text(const char *path) {
  std::ifstream input(path);
  std::ostringstream buffer;
  buffer << input.rdbuf();
  return buffer.str();
}

void dumpMol(const RDKit::ROMol &m, const char *label) {
  std::cerr << "=== " << label << " ===\n";
  for (const auto a : m.atoms()) {
    std::cerr << "  atom " << a->getIdx() << " " << a->getSymbol()
              << " hyb=" << a->getHybridization()
              << " chiral=" << a->getChiralTag()
              << " deg=" << a->getDegree() << " totH=" << a->getTotalNumHs()
              << " arom=" << a->getIsAromatic() << "\n";
  }
  for (const auto b : m.bonds()) {
    std::cerr << "  bond " << b->getIdx() << " " << b->getBeginAtomIdx() << "-"
              << b->getEndAtomIdx() << " type=" << b->getBondType()
              << " dir=" << b->getBondDir() << " stereo=" << b->getStereo()
              << " stereoAtoms=[";
    for (auto sa : b->getStereoAtoms()) {
      std::cerr << sa << " ";
    }
    std::cerr << "] arom=" << b->getIsAromatic() << "\n";
  }
}

#define TRY_STEP(name, expr)                                          \
  try {                                                               \
    std::cerr << "--- step: " << name << "\n";                        \
    expr;                                                             \
    std::cerr << "--- ok: " << name << "\n";                          \
  } catch (const Invar::Invariant &e) {                               \
    std::cerr << "!!! INVARIANT in " << name << ": " << e.getMessage() \
              << "\n";                                                \
  } catch (const std::exception &e) {                                 \
    std::cerr << "!!! EXC in " << name << ": " << e.what() << "\n";   \
  }

}  // namespace

int main(int argc, char **argv) {
  const auto molblock = read_text(argv[1]);
  RDKit::RWMol *raw = RDKit::MolBlockToMol(molblock);
  if (!raw) {
    std::cerr << "load failed\n";
    return 3;
  }
  std::unique_ptr<RDKit::RWMol> mol(raw);
  dumpMol(*mol, "loaded");
  TRY_STEP("smiles_isomeric_noncanon",
           std::cerr << RDKit::MolToSmiles(*mol, false, true) << "\n");
  TRY_STEP("smiles_isomeric_canon",
           std::cerr << RDKit::MolToSmiles(*mol, true, true) << "\n");

  RDKit::MolStandardize::TautomerEnumerator enumerator;
  enumerator.setRemoveBondStereo(false);

  TRY_STEP("enumerate", {
    auto res = enumerator.enumerate(*mol);
    std::cerr << "  n tautomers: " << res.size()
              << " status=" << static_cast<int>(res.status()) << "\n";
    int i = 0;
    for (const auto &t : res) {
      ++i;
      TRY_STEP("taut smiles " + std::to_string(i), {
        std::cerr << "  taut " << i << ": "
                  << RDKit::MolToSmiles(*t, false, true) << "\n";
      });
      dumpMol(*t, ("tautomer " + std::to_string(i)).c_str());
    }
  });

  TRY_STEP("canonicalize", {
    std::unique_ptr<RDKit::ROMol> canonical(enumerator.canonicalize(*mol));
    std::cerr << "  canonical ptr: " << (void *)canonical.get() << "\n";
    if (canonical) {
      dumpMol(*canonical, "canonical");
      TRY_STEP("canonical smiles noncanon",
               std::cerr << RDKit::MolToSmiles(*canonical, false, true)
                         << "\n");
      TRY_STEP("canonical smiles canon", std::cerr
                                             << RDKit::MolToSmiles(*canonical,
                                                                   true, true)
                                             << "\n");
    }
  });
  return 0;
}

