  PRECONDITION(dblBond->getBondType() == Bond::DOUBLE, "bad bond order");
  if (!(dblBond->getStereo() > Bond::STEREOANY)) {
    void *bt[64];
    int n = backtrace(bt, 64);
    char **syms = backtrace_symbols(bt, n);
    fprintf(stderr, "DEBUG bad bond stereo: bond %u %u-%u stereo=%d natoms=%zu\n",
            dblBond->getIdx(), dblBond->getBeginAtomIdx(),
            dblBond->getEndAtomIdx(), (int)dblBond->getStereo(),
            dblBond->getStereoAtoms().size());
    for (int i = 0; i < n; ++i) fprintf(stderr, "  %s\n", syms[i]);
  }
  PRECONDITION(dblBond->getStereo() > Bond::STEREOANY, "bad bond stereo");

