25	constexpr double REALLY_SMALL_BOND_LEN = 0.0000001;
26	
27	namespace RDKit {
28	namespace Atropisomers {
29	
30	bool getAtropisomerAtomsAndBonds(const Bond *bond,
31	                                 AtropAtomAndBondVec atomsAndBondVects[2],
32	                                 const ROMol &mol) {
33	  PRECONDITION(bond, "no bond");
34	  atomsAndBondVects[0].first = bond->getBeginAtom();
35	  atomsAndBondVects[1].first = bond->getEndAtom();
36	
37	  // get the one or two bonds on each end
38	
39	  for (int bondAtomIndex = 0; bondAtomIndex < 2; ++bondAtomIndex) {
40	    for (const auto nbrBond :
41	         mol.atomBonds(atomsAndBondVects[bondAtomIndex].first)) {
42	      if (nbrBond == bond) {
43	        continue;  // a bond is NOT its own neighbor
44	      }
45	      atomsAndBondVects[bondAtomIndex].second.push_back(nbrBond);
46	    }
47	    if (atomsAndBondVects[bondAtomIndex].second.size() == 0) {
48	      return false;  // no neighbor bonds found
49	    }
50	
51	    // make sure the bond with this lowest atom is is first
52	
53	    if (atomsAndBondVects[bondAtomIndex].second.size() == 2 &&
54	        atomsAndBondVects[bondAtomIndex]
55	                .second[1]
56	                ->getOtherAtom(atomsAndBondVects[bondAtomIndex].first)
57	                ->getIdx() <
58	            atomsAndBondVects[bondAtomIndex]
59	                .second[0]
60	                ->getOtherAtom(atomsAndBondVects[bondAtomIndex].first)
61	                ->getIdx()) {
62	      std::swap(atomsAndBondVects[bondAtomIndex].second[0],
63	                atomsAndBondVects[bondAtomIndex].second[1]);
64	    }
65	  }
66	
67	  return true;
68	}
69	
70	bool getBondFrameOfReference(const Bond *bond, const Conformer *conf,
71	                             RDGeom::Point3D &xAxis, RDGeom::Point3D &yAxis,
72	                             RDGeom::Point3D &zAxis) {
73	  // create a frame of reference that has its X-axis along the atrop bond
74	  // for 2D confs, the yAxis is in the 2D plane and the zAxis is perpendicular
75	  // to that plane) for 3D confs  the yAxis and the zAxis are arbitrary.
76	
77	  PRECONDITION(bond, "bad bond");
78	
79	  xAxis = conf->getAtomPos(bond->getEndAtom()->getIdx()) -
80	          conf->getAtomPos(bond->getBeginAtom()->getIdx());
81	  if (xAxis.length() < REALLY_SMALL_BOND_LEN) {
82	    return false;  // bond len is xero
83	  }
84	  xAxis.normalize();
85	  if (!conf->is3D()) {
86	    yAxis = RDGeom::Point3D(-xAxis.y, xAxis.x, 0);
87	    yAxis.normalize();
88	    zAxis = RDGeom::Point3D(0.0, 0.0, 1.0);
89	    return true;
90	  }
91	
92	  // here for 3D conf
93	
94	  if (fabs(xAxis.x) > REALLY_SMALL_BOND_LEN ||
95	      fabs(xAxis.y) > REALLY_SMALL_BOND_LEN) {
96	    zAxis = RDGeom::Point3D(
97	        0, 0, 1);  // since X or Y value of the new x xaxis is NOT 0, this
98	                   // new temp z axis cannnot be colinear with it
99	  } else {
100	    zAxis = RDGeom::Point3D(1, 0, 0);  // since the new x axis is exactly along
101	                                       // the (old) z axis, this new temp z axis
102	                                       // is NOT colinear with it
103	  }
104	
105	  yAxis = zAxis.crossProduct(xAxis);
106	  zAxis = xAxis.crossProduct(yAxis);
107	  yAxis.normalize();
108	  zAxis.normalize();
109	
110	  return true;
111	}
112	
113	Bond::BondDir getBondDirForAtropisomerNoConf(Bond::BondStereo bondStereo,
114	                                             unsigned int whichEnd,
115	                                             unsigned int whichBond) {
116	  // the convention is that in the absence of coords, the coordiates are choosen
117	  // with the lowest numbered atom of the atrop bond down, and the other atom
118	  // straight up.
119	  // On each end, the lowest numbered connecting atom is on the left
120	  //
121	  //              a      b
122	  //               \   /
123	  //                 c
124	  //                 |
125	  //                 d
126	  //               /   \     aaa
127	  //              e      f
128	  //
129	  // where  c > d
130	  //        a < b
131	  //        e < f
132	
133	  PRECONDITION(whichEnd <= 1, "whichEnd must be 0 or 1");
134	  PRECONDITION(whichBond <= 1, "whichBond must be 0 or 1");
135	  PRECONDITION(bondStereo == Bond::BondStereo::STEREOATROPCW ||
136	                   bondStereo == Bond::BondStereo::STEREOATROPCCW,
137	               "bondStereo must be BondAtropisomerCW or BondAtropisomerCCW");
138	
139	  int flips = 0;
140	  if (bondStereo == Bond::BondStereo::STEREOATROPCW) {
141	    ++flips;
142	  }
143	  if (whichBond == 1) {
144	    ++flips;
145	  }
146	  if (whichEnd == 1) {
147	    ++flips;
148	  }
149	
150	  return flips % 2 ? Bond::BEGINDASH : Bond::BEGINWEDGE;
151	}
152	
153	Bond::BondDir getBondDirForAtropisomer2d(RDGeom::Point3D bondVecs[2],
154	                                         Bond::BondStereo bondStereo,
155	                                         unsigned int whichEnd,
156	                                         unsigned int whichBond) {
157	  PRECONDITION(whichEnd <= 1, "whichEnd must be 0 or 1");
158	  PRECONDITION(whichBond <= 1, "whichBond must be 0 or 1");
159	  PRECONDITION(bondStereo == Bond::BondStereo::STEREOATROPCW ||
160	                   bondStereo == Bond::BondStereo::STEREOATROPCCW,
161	               "bondStereo must be BondAtropisomerCW or BondAtropisomerCCW");
162	
163	  int flips = 0;
164	  if (bondStereo == Bond::BondStereo::STEREOATROPCCW) {
165	    ++flips;
166	  }
167	  if (whichBond == 1) {
168	    ++flips;
169	  }
170	  if (whichEnd == 1) {
171	    ++flips;
172	  }
173	  if (bondVecs[1 - whichEnd].y < 0) {
174	    ++flips;  // if the OTHER end is negative for the low index bond vec, it
175	              // is a flip
176	  }
177	
178	  return flips % 2 ? Bond::BEGINWEDGE : Bond::BEGINDASH;
179	}
180	
181	Bond::BondDir getBondDirForAtropisomer3d(Bond *whichBond,
182	                                         const Conformer *conf) {
183	  // for 3D we mark it as wedge or hash depending on the z-value of the bond
184	  // vector
185	  //  IT really doesn't matter since we ignore these except as MARKERS for
186	  //  which bonds are atropisomer bonds
187	  if ((conf->getAtomPos(whichBond->getEndAtom()->getIdx()).z -
188	       conf->getAtomPos(whichBond->getBeginAtom()->getIdx()).z) >
189	      REALLY_SMALL_BOND_LEN) {
190	    return Bond::BondDir::BEGINWEDGE;
191	  } else {
192	    return Bond::BondDir::BEGINDASH;
193	  }
194	}
195	
196	bool getAtropIsomerEndVect(const AtropAtomAndBondVec &atomAndBondVec,
197	                           const RDGeom::Point3D &yAxis,
198	                           const RDGeom::Point3D &zAxis, const Conformer *conf,
199	                           RDGeom::Point3D &bondVec) {
200	  PRECONDITION(
201	      atomAndBondVec.second.size() > 0 && atomAndBondVec.second.size() < 3,
202	      "bad bond size");
203	  PRECONDITION(atomAndBondVec.second[0], "bad first bond");
204	  PRECONDITION(atomAndBondVec.second.size() == 1 || atomAndBondVec.second[1],
205	               "bad second bond");
206	
207	  bondVec = conf->getAtomPos(atomAndBondVec.second[0]
208	                                 ->getOtherAtom(atomAndBondVec.first)
209	                                 ->getIdx()) -
210	            conf->getAtomPos(
211	                atomAndBondVec.first->getIdx());  // in old frame of reference
212	
213	  bondVec = RDGeom::Point3D(0.0, bondVec.dotProduct(yAxis),
214	                            bondVec.dotProduct(zAxis));  // in new frame
215	
216	  // make sure the other atom is on the other side
217	
218	  if (atomAndBondVec.second.size() == 2) {
219	    RDGeom::Point3D otherVec =
220	        conf->getAtomPos(atomAndBondVec.second[1]
221	                             ->getOtherAtom(atomAndBondVec.first)
222	                             ->getIdx()) -
223	        conf->getAtomPos(
224	            atomAndBondVec.first->getIdx());  // in old frame of reference
225	    otherVec = RDGeom::Point3D(0.0, otherVec.dotProduct(yAxis),
226	                               otherVec.dotProduct(zAxis));  // in new frame
227	
228	    if (bondVec.length() < REALLY_SMALL_BOND_LEN) {
229	      bondVec = -otherVec;  // put it on the other side of otherVec
230	    } else if (bondVec.dotProduct(otherVec) > REALLY_SMALL_BOND_LEN) {
231	      // the product of dotproducts (y-values) should be
232	      // negative (or at least zero)
233	      BOOST_LOG(rdWarningLog)
234	          << "Both bonds on one end of an atropisomer are on the same side - atoms is : "
235	          << atomAndBondVec.first->getIdx() << std::endl;
236	      return false;
237	    }
238	  }
239	  if (bondVec.length() < REALLY_SMALL_BOND_LEN) {
240	    BOOST_LOG(rdWarningLog)
241	        << "Could not find a bond on one end of an atropisomer that is not co-linear - atoms are : "
242	        << atomAndBondVec.first->getIdx() << std::endl;
243	    return false;
244	  }
245	
246	  bondVec.normalize();
247	  return true;
248	}
249	
250	std::pair<bool, Bond::BondDir> getBondDir(
251	    const Bond *bond, const AtropAtomAndBondVec &atomAndBondVec) {
252	  // get the wedge dir for this end of the bond
253	  // if the first bond 1 has a bondDir, use it
254	  // if the second bond has a bond dir use the opposite of if
255	  // if both bonds have a dir, make sure they are different
256	
257	  auto bond1Dir = atomAndBondVec.second[0]->getBondDir();
258	  if (bond1Dir != Bond::BEGINWEDGE && bond1Dir != Bond::BEGINDASH) {
259	    bond1Dir = Bond::NONE;  //  we dont care if it any thing else
260	  }
261	  auto bond2Dir = atomAndBondVec.second.size() == 2
262	                      ? atomAndBondVec.second[1]->getBondDir()
263	                      : Bond::NONE;
264	  if (bond2Dir != Bond::BEGINWEDGE && bond2Dir != Bond::BEGINDASH) {
265	    bond2Dir = Bond::NONE;
266	  }
267	
268	  // if both are set to a direction, they must NOT be the same - one
269	  // must be a dash and the other a hash
270	
271	  if (bond1Dir != Bond::NONE && bond2Dir != Bond::NONE &&
272	      bond1Dir == bond2Dir) {
273	    BOOST_LOG(rdWarningLog)
274	        << "The bonds on one end of an atropisomer are both UP or both DOWN - atoms are: "
275	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
276	    return {false, Bond::BondDir::NONE};
277	  }
278	
279	  if (bond1Dir == Bond::BEGINWEDGE || bond2Dir == Bond::BEGINDASH) {
280	    return {true, Bond::BondDir::BEGINWEDGE};
281	  }
282	  if (bond1Dir == Bond::BEGINDASH || bond2Dir == Bond::BEGINWEDGE) {
283	    return {true, Bond::BondDir::BEGINDASH};
284	  }
285	  return {true, Bond::BondDir::NONE};
286	}
287	
288	void DetectAtropisomerChiralityOneBond(Bond *bond, ROMol &mol,
289	                                       const Conformer *conf) {
290	  // the approach is this:
291	  // we will view the system along the line from the potential atropisomer
292	  // bond, from atom1 to atom 2 and we do a coordinate transformation to
293	  // the plane of reference where that vector, from a1 to a2, is the x-AXIS.
294	  // For 2D, the y axis is in the 2D plane, and the zaxis is perpendicaul to
295	  // the 2D plane For 3D, the Y and Z axes are taken arbitrarily to form
296	  // a right-handed system with the X-axis.
297	  //  atoms 1 and 2 each have one or two bonds out from the main potential
298	  //  atrop bond. for each end of the main bond, we find a vector to reprent
299	  //  the neighbor atom with the smallest index as its projection onto the
300	  //  x=0 plane.
301	  // (In 2d, this projection is on the y-AXIS for the end that does NOT have
302	  // a wedge/hash bond, and  on the z axis - out of the plane - for the end
303	  // that does have a wedge/hash). The chirality is recorded as the
304	  // direction we rotate from, atom 1's projection to atom2's proejection -
305	  // either clockwise or counter clockwise
306	
307	  PRECONDITION(bond, "bad bond");
308	
309	  // one vector for each end - each one - should end up with 1 or 2 entries
310	  AtropAtomAndBondVec atomAndBondVecs[2];
311	  if (!getAtropisomerAtomsAndBonds(bond, atomAndBondVecs, mol)) {
312	    return;  // not an atropisomer
313	  }
314	
315	  // make sure we do not have wiggle bonds
316	
317	  for (auto atomAndBondVec : atomAndBondVecs) {
318	    for (auto endBond : atomAndBondVec.second) {
319	      if (endBond->getBondDir() == Bond::UNKNOWN) {
320	        return;  // not an atropisomer
321	      }
322	    }
323	  }
324	
325	  // the convention is that in the absence of coords, the coordiates are choosen
326	  // with the lowest numbered atom of the atrop bond down, and the other atom
327	  // straight up.
328	  // On each end, the lowest numbered connecting atom is on the left
329	  //
330	  //              a      b
331	  //               \   /
332	  //                 c
333	  //                 |
334	  //                 d
335	  //               /   \     aaa
336	  //              e      f
337	  //
338	  // where  c > d
339	  //        a < b
340	  //        e < f
341	
342	  if (conf == nullptr) {
343	    std::pair<bool, Bond::BondDir> bond1DirResult;
344	    bond1DirResult = getBondDir(bond, atomAndBondVecs[0]);
345	    if (!bond1DirResult.first) {
346	      return;
347	    }
348	    std::pair<bool, Bond::BondDir> bond2DirResult;
349	    bond2DirResult = getBondDir(bond, atomAndBondVecs[1]);
350	    if (!bond2DirResult.first) {
351	      return;
352	    }
353	    if (bond1DirResult.second == bond2DirResult.second) {
354	      BOOST_LOG(rdWarningLog)
355	          << "inconsistent bond wedging for an atropisomer.  Atoms are: "
356	          << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
357	          << std::endl;
358	      return;
359	    }
360	
361	    if (bond1DirResult.second == Bond::BEGINWEDGE ||
362	        bond2DirResult.second == Bond::BEGINDASH) {
363	      bond->setStereo(Bond::BondStereo::STEREOATROPCCW);
364	    } else if (bond1DirResult.second == Bond::BEGINDASH ||
365	               bond2DirResult.second == Bond::BEGINWEDGE) {
366	      bond->setStereo(Bond::BondStereo::STEREOATROPCW);
367	    }
368	
369	    return;
370	  }
371	
372	  // create a frame of reference that has its X-axis along the atrop bond
373	
374	  RDGeom::Point3D xAxis, yAxis, zAxis;
375	  if (!getBondFrameOfReference(bond, conf, xAxis, yAxis, zAxis)) {
376	    // connot percieve atroisomer
377	    BOOST_LOG(rdWarningLog)
378	        << "Failed to get a frame of reference along an atropisomer bond - atoms are: "
379	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
380	    return;
381	  }
382	  RDGeom::Point3D bondVecs[2];  // one bond vector from each end of the
383	                                // potential atropisomer bond
384	
385	  for (int bondAtomIndex = 0; bondAtomIndex < 2; ++bondAtomIndex) {
386	    // if the conf is 2D, we use the wedge bonds to set the coords for the
387	    // projected vector onto the xAxis perpendicular plane (looking down
388	    // the atrop bond )
389	
390	    if (!conf->is3D()) {
391	      // get the wedge dir for this end of the bond
392	      // if the first bond 1 has a bondDir, use it
393	      // if the second bond has a bond dir use the opposite of if
394	      // if both bonds have a dir, make sure they are different
395	
396	      std::pair<bool, Bond::BondDir> bondDirResult;
397	
398	      bondDirResult = getBondDir(bond, atomAndBondVecs[bondAtomIndex]);
399	      if (!bondDirResult.first) {
400	        return;
401	      }
402	
403	      if (!getAtropIsomerEndVect(atomAndBondVecs[bondAtomIndex], yAxis, zAxis,
404	                                 conf, bondVecs[bondAtomIndex])) {
405	        return;
406	      }
407	
408	      if (bondDirResult.second == Bond::BEGINWEDGE) {
409	        bondVecs[bondAtomIndex].y *= 0.707;
410	        bondVecs[bondAtomIndex].z = fabs(bondVecs[bondAtomIndex].y);
411	      } else if (bondDirResult.second == Bond::BEGINDASH) {
412	        bondVecs[bondAtomIndex].y *= 0.707;
413	        bondVecs[bondAtomIndex].z = -fabs(bondVecs[bondAtomIndex].y);
414	      }
415	    } else {  // the conf is 3D
416	      // to be considered, one or more neighbor bonds must have a wedge or
417	      // hash
418	
419	      // find the projection of the bond(s) on this end in the frame of
420	      // reference's  x=0  plane
421	      RDGeom::Point3D tempBondVec =
422	          conf->getAtomPos(
423	              atomAndBondVecs[bondAtomIndex]
424	                  .second[0]
425	                  ->getOtherAtom(atomAndBondVecs[bondAtomIndex].first)
426	                  ->getIdx()) -
427	          conf->getAtomPos(atomAndBondVecs[bondAtomIndex].first->getIdx());
428	      bondVecs[bondAtomIndex] = RDGeom::Point3D(
429	          0.0, tempBondVec.dotProduct(yAxis), tempBondVec.dotProduct(zAxis));
430	
431	      if (atomAndBondVecs[bondAtomIndex].second.size() == 2) {
432	        tempBondVec =
433	            conf->getAtomPos(
434	                atomAndBondVecs[bondAtomIndex]
435	                    .second[1]
436	                    ->getOtherAtom(atomAndBondVecs[bondAtomIndex].first)
437	                    ->getIdx()) -
438	            conf->getAtomPos(atomAndBondVecs[bondAtomIndex].first->getIdx());
439	
440	        // get the projection of the 2nd bond on the x=0 plane
441	
442	        RDGeom::Point3D otherBondVec = RDGeom::Point3D(
443	            0.0, tempBondVec.dotProduct(yAxis), tempBondVec.dotProduct(zAxis));
444	
445	        // if the first atom is co-linear with the main atrop bond, use
446	        // the opposite of the 2nd atom
447	
448	        if (bondVecs[bondAtomIndex].length() < REALLY_SMALL_BOND_LEN) {
449	          bondVecs[bondAtomIndex] =
450	              -otherBondVec;  // note - it might still be co-linear-
451	                              // this is checked below
452	        } else if (bondVecs[bondAtomIndex].dotProduct(otherBondVec) >
453	                   REALLY_SMALL_BOND_LEN) {
454	          BOOST_LOG(rdWarningLog)
455	              << "Both bonds on one end of an atropisomer are on the same side - atoms are: "
456	              << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
457	              << std::endl;
458	          return;
459	        }
460	      }
461	
462	      if (bondVecs[bondAtomIndex].length() < REALLY_SMALL_BOND_LEN) {
463	        BOOST_LOG(rdWarningLog)
464	            << "Failed to find a bond on one end of an atropisomer that is NOT co-linear - atoms are: "
465	            << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
466	            << std::endl;
467	        return;
468	      }
469	    }
470	  }
471	
472	  auto crossProduct = bondVecs[1].crossProduct(bondVecs[0]);
473	
474	  if (crossProduct.x > REALLY_SMALL_BOND_LEN) {
475	    bond->setStereo(Bond::BondStereo::STEREOATROPCCW);
476	  } else if (crossProduct.x < -REALLY_SMALL_BOND_LEN) {
477	    bond->setStereo(Bond::BondStereo::STEREOATROPCW);
478	  } else {
479	    BOOST_LOG(rdWarningLog)
480	        << "The 2 defining bonds for an atropisomer are co-planar - atoms are: "
481	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
482	    return;
483	  }
484	}
485	
486	void cleanupAtropisomerStereoGroups(ROMol &mol) {
487	  std::vector<StereoGroup> newsgs;
488	  for (auto sg : mol.getStereoGroups()) {
489	    std::vector<Atom *> okatoms;
490	    std::vector<Bond *> okbonds;
491	
492	    for (auto atom : sg.getAtoms()) {
493	      bool foundAtrop = false;
494	      for (auto bndI : boost::make_iterator_range(mol.getAtomBonds(atom))) {
495	        auto bond = (mol)[bndI];
