497	            bond->getStereo() == Bond::BondStereo::STEREOATROPCW) {
498	          foundAtrop = true;
499	          if (std::find(okbonds.begin(), okbonds.end(), bond) ==
500	              okbonds.end()) {
501	            okbonds.push_back(bond);
502	          }
503	        }
504	      }
505	
506	      if (!foundAtrop) {
507	        okatoms.push_back(atom);
508	      }
509	    }
510	
511	    if (okbonds.empty()) {
512	      newsgs.push_back(sg);
513	    } else {
514	      newsgs.emplace_back(sg.getGroupType(), std::move(okatoms),
515	                          std::move(okbonds));
516	    }
517	  }
518	  mol.setStereoGroups(std::move(newsgs));
