602	void getAllAtomIdsForStereoGroup(
603	    const ROMol &mol, const StereoGroup &group,
604	    std::vector<unsigned int> &atomIds,
605	    const std::map<int, std::unique_ptr<RDKit::Chirality::WedgeInfoBase>>
606	        &wedgeBonds) {
607	  atomIds.clear();
608	  for (auto &&atom : group.getAtoms()) {
609	    atomIds.push_back(atom->getIdx());
610	  }
611	
612	  for (auto &&bond : group.getBonds()) {
613	    // figure out which atoms of the bond get wedge/hash indications
614	    // mark the atom with the wedge/hash
615	
616	    for (auto atom : {bond->getBeginAtom(), bond->getEndAtom()}) {
617	      for (const auto atomBond : mol.atomBonds(atom)) {
618	        if (atomBond->getIdx() == bond->getIdx()) {
619	          continue;
620	        }
621	
622	        if (atomBond->getBondDir() == Bond::BEGINWEDGE ||
623	            atomBond->getBondDir() == Bond::BEGINDASH ||
624	            (wedgeBonds.find(atomBond->getIdx()) != wedgeBonds.end() &&
625	             (wedgeBonds.at(atomBond->getIdx())->getType()) ==
626	                 Chirality::WedgeInfoType::WedgeInfoTypeAtropisomer)) {
627	          if (std::find(atomIds.begin(), atomIds.end(), atom->getIdx()) ==
628	              atomIds.end()) {
629	            atomIds.push_back(atom->getIdx());
630	          }
631	        }
632	      }
633	    }
634	  }
