#include <GraphMol/MolStandardize/Tautomer.h>
#include <GraphMol/RDKitBase.h>
#include <GraphMol/SmilesParse/SmilesParse.h>
#include <GraphMol/SmilesParse/SmilesWrite.h>

#include <exception>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

namespace {

template <typename F>
std::string attempt(F &&f) {
  try {
    return f();
  } catch (const std::exception &e) {
    return std::string("EXC:") + e.what();
  } catch (...) {
    return std::string("EXC:unknown");
  }
}

}  // namespace

int main() {
  std::vector<std::string> cases = {
      // plain stereo
      "C/C=C/C", "C/C=C\\C", "F/C=C/F", "F/C=C\\Cl",
      // adjacent/coupled double bond stereo (exercises neighbor follow logic)
      "C/C=C/C=C/C", "C/C=C\\C=C/C", "C/C=C\\C=C\\C",
      "F/C=C/C=C/F", "F/C=C\\C=C\\F",
      // stereo in rings
      "C1=CCCCCC1", "C/C=C\\CCCC1=CCCCC1",
      "C[C@H]1CC[C@@H](C)CC1", "C[C@@H]1CCC[C@H]1C",
      // chiral centers, meso
      "N[C@@H](C)C(=O)O", "C(C(C(C)O)O)O",
      // crossed/unknown double bond (wavy) semantics
      "FC=CF |w:1.1|",
      // allene/cumulene-ish
      "CC=C=CC", "C/C=C=C/C",
      // tautomerizable sets with stereo
      "C/C=C\\NC(C)=O", "CC(O)=CC", "C/C=C/O",
      "C/C=C\\C[C@@H](O)C(=O)N[C@H](C)C(=O)O",
      "O=c1[nH]cccc1C[C@@H](C)O", "C(=NO)c1ccccc1",
      "C[C@H](N)C(=N)N", "CCCN=C(C)O",
      // amide + stereo double bond conjugation (neighbor-scan trigger)
      "C/C=C\\N=C(C)O",
      // atrop-bearing single bond + E/Z double bond (fixture-like, via CXSMILES)
      "C=C(C)c1cccc([C@@H](C)O)c1 |wD:3.3|",
      // heteroaromatic tautomer favorites
      "Oc1ccccn1", "Oc1cccnc1", "c1ccc2[nH]ncc2c1",
      // bigger/drug-like with stereo
      "CC[C@H](C)[C@@H](O)CC(=O)N1CCC[C@H]1C(=O)O",
      "CN1CCC[C@@H]1c1cccnc1",
  };

  for (const auto &in : cases) {
    std::unique_ptr<RDKit::ROMol> m(RDKit::SmilesToMol(in));
    if (!m) {
      std::cout << "PARSE_FAIL " << in << "\n";
      continue;
    }
    std::cout << "IN " << in << "\n";
    std::cout << "  smiles_canon  : "
              << attempt([&] { return RDKit::MolToSmiles(*m, true, true); })
              << "\n";
    for (bool rbs : {true, false}) {
      std::cout << "  canon rbs=" << rbs << "     : "
                << attempt([&] {
                     RDKit::MolStandardize::TautomerEnumerator enumerator;
                     enumerator.setRemoveBondStereo(rbs);
                     std::unique_ptr<RDKit::ROMol> canonical(
                         enumerator.canonicalize(*m));
                     if (!canonical) {
                       return std::string("NULL");
                     }
                     return RDKit::MolToSmiles(*canonical, true, true);
                   })
                << "\n";
    }
  }
  return 0;
}

